# add_process ----
## Setup ----
# `small_parameters` is in helper-small-parameters.R.
# A per-age target with no years.
parameters_with_init_naa <- small_parameters |>
  dplyr::bind_rows(tibble::tibble(
    module_name = "Population",
    label = "log_init_naa",
    age = 1:4,
    value = 10,
    estimation_type = "fixed_effects"
  ))

## IO correctness ----
test_that("`add_process()` writes 1 row per year with a map_group for time blocks", {
  log_q_rows <- small_parameters |>
    add_process(
      log_q ~ cut(year, c(-Inf, 2, 4, Inf)),
      module_name = "Fleet",
      fleet = "survey1"
    ) |>
    dplyr::filter(label == "log_q")
  #' @description Test that `add_process()` with time blocks writes 1 row per year.
  expect_equal(
    object = log_q_rows[["timing"]],
    expected = 1:6
  )
  #' @description Test that `add_process()` gives the years in each time block the same map_group.
  expect_equal(
    object = log_q_rows[["map_group"]],
    expected = c(1L, 1L, 2L, 2L, 3L, 3L)
  )
  #' @description Test that `add_process()` with time blocks keeps the rows as fixed effects.
  expect_true(all(log_q_rows[["estimation_type"]] == "fixed_effects"))
  #' @description Test that `add_process()` with time blocks copies the starting value to every year.
  expect_equal(
    object = log_q_rows[["value"]],
    expected = rep(-2, 6)
  )
  block_breaks <- c(-Inf, 2, 4, Inf)
  #' @description Test that `add_process()` finds variables, such as the breaks, where the formula was written.
  expect_equal(
    object = small_parameters |>
      add_process(
        log_q ~ cut(year, block_breaks),
        module_name = "Fleet",
        fleet = "survey1"
      ) |>
      dplyr::filter(label == "log_q") |>
      dplyr::pull(map_group),
    expected = log_q_rows[["map_group"]]
  )
})

test_that("`add_process()` starts each time block from the mean of its rows", {
  log_fmort_rows <- small_parameters |>
    dplyr::mutate(
      value = dplyr::if_else(label == "log_Fmort", -(1:7) / 2, value)
    ) |>
    add_process(
      log_Fmort ~ cut(year, c(-Inf, 3, Inf)),
      module_name = "Fleet",
      fleet = "fleet1"
    ) |>
    dplyr::filter(label == "log_Fmort")
  #' @description Test that `add_process()` starts rows that share 1 estimate from the same value, the mean of the block.
  expect_equal(
    object = log_fmort_rows[["value"]],
    expected = rep(c(-1.5, -3), each = 3)
  )
})

test_that("`add_process()` writes the rows of an AR1 process around time blocks", {
  # AR1 around 2 block means.
  parameters <- small_parameters |>
    add_process(
      log_q ~ cut(year, c(-Inf, 3, Inf)) + ar1(1 | year),
      module_name = "Fleet",
      fleet = "survey1",
      sd = list(value = 0.1, estimation_type = "fixed_effects"),
      rho = list(value = 0.5, estimation_type = "fixed_effects")
    )
  log_q_rows <- dplyr::filter(parameters, label == "log_q")
  expected_mean_rows <- dplyr::filter(parameters, label == "expected_mean")
  #' @description Test that `add_process()` makes each year of an AR1 target a random effect.
  expect_true(all(log_q_rows[["estimation_type"]] == "random_effects"))
  #' @description Test that `add_process()` writes ar1 as the re_structure of the target rows.
  expect_true(all(log_q_rows[["re_structure"]] == "ar1"))
  #' @description Test that `add_process()` gives each random effect its own estimate, with no map_group.
  expect_true(all(is.na(log_q_rows[["map_group"]])))
  #' @description Test that `add_process()` writes 1 expected_mean row per year, shared within each time block.
  expect_equal(
    object = expected_mean_rows[["map_group"]],
    expected = c(1L, 1L, 1L, 2L, 2L, 2L)
  )
  #' @description Test that `add_process()` names the target in the target_label of the expected_mean rows.
  expect_true(all(expected_mean_rows[["target_label"]] == "log_q"))
  #' @description Test that `add_process()` writes the process sd on the log scale.
  expect_equal(
    object = dplyr::filter(parameters, label == "log_sd")[["value"]],
    expected = log(0.1)
  )
  #' @description Test that `add_process()` writes rho = 0.5 as logit_rho = log(3).
  expect_equal(
    object = dplyr::filter(parameters, label == "logit_rho")[["value"]],
    expected = log(3)
  )
})

test_that("`add_process()` makes the first year of a random walk a fixed effect", {
  parameters <- small_parameters |>
    add_process(
      log_q ~ rw(1 | year),
      module_name = "Fleet",
      fleet = "survey1"
    )
  #' @description Test that `add_process()` makes the first year of a random walk a fixed effect and the other years random effects.
  expect_equal(
    object = dplyr::filter(parameters, label == "log_q")[["estimation_type"]],
    expected = c("fixed_effects", rep("random_effects", 5))
  )
  #' @description Test that `add_process()` writes no expected_mean row for a random walk.
  expect_false("expected_mean" %in% parameters[["label"]])
})

## Edge handling ----
test_that("`add_process()` returns correct outputs for edge cases", {
  log_init_naa_rows <- parameters_with_init_naa |>
    add_process(
      log_init_naa ~ cut(age, c(-Inf, 2, Inf)),
      module_name = "Population"
    ) |>
    dplyr::filter(label == "log_init_naa")
  #' @description Test that `add_process()` with age blocks on a target with no years keeps 1 row per age.
  expect_equal(
    object = nrow(log_init_naa_rows),
    expected = 4
  )
  #' @description Test that `add_process()` with age blocks on a target with no years does not add years.
  expect_true(all(is.na(log_init_naa_rows[["timing"]])))
  #' @description Test that `add_process()` gives the ages in each age block the same map_group.
  expect_equal(
    object = log_init_naa_rows[["map_group"]],
    expected = c(1L, 1L, 2L, 2L)
  )

  # `estimation_status` and "not_estimated" are other names for
  # `estimation_type` and "constant".
  aliased <- small_parameters |>
    add_process(
      log_q ~ 1 + ar1(1 | year),
      module_name = "Fleet",
      fleet = "survey1",
      sd = list(value = 0.1, estimation_status = "constant"),
      rho = list(value = 0.5, estimation_type = "not_estimated")
    )
  #' @description Test that `add_process()` reads `estimation_status` in the sd list as the estimation type of the log_sd row.
  expect_equal(
    object = dplyr::filter(aliased, label == "log_sd")[["estimation_type"]],
    expected = "constant"
  )
  #' @description Test that `add_process()` writes an estimation type of "not_estimated" as "constant".
  expect_equal(
    object = dplyr::filter(aliased, label == "logit_rho")[["estimation_type"]],
    expected = "constant"
  )
})

## Error handling ----
test_that("`add_process()` returns correct error messages", {
  #' @description Test that `add_process()` errors for a random walk around time blocks.
  expect_error(
    object = add_process(
      small_parameters,
      log_q ~ cut(year, c(-Inf, 3, Inf)) + rw(1 | year),
      module_name = "Fleet",
      fleet = "survey1"
    ),
    regexp = "random walk"
  )
  blocked <- add_process(
    small_parameters,
    log_q ~ cut(year, c(-Inf, 3, Inf)),
    module_name = "Fleet",
    fleet = "survey1"
  )
  #' @description Test that `add_process()` errors on a second call for the same target.
  expect_error(
    object = add_process(
      blocked,
      log_q ~ 1 + (1 | year),
      module_name = "Fleet",
      fleet = "survey1"
    ),
    regexp = "1 call per target"
  )
  #' @description Test that `add_process()` errors when the breaks leave some years outside every time block, so the fixed term gives NA.
  expect_error(
    object = add_process(
      small_parameters,
      log_q ~ cut(year, c(3, Inf)),
      module_name = "Fleet",
      fleet = "survey1"
    ),
    regexp = "NA"
  )
  #' @description Test that `add_process()` errors for additive fixed terms, which need a design matrix, not a map.
  expect_error(
    object = add_process(
      small_parameters,
      log_q ~ cut(year, c(-Inf, 3, Inf)) + factor(year),
      module_name = "Fleet",
      fleet = "survey1"
    ),
    regexp = "design"
  )
  #' @description Test that `add_process()` warns when the process is penalized (fixed effects) and its sd is estimated, because the objective is unbounded as the sd goes to 0.
  expect_warning(
    object = add_process(
      small_parameters,
      log_q ~ 1 + (1 | year),
      module_name = "Fleet",
      fleet = "survey1",
      estimation_type = "fixed_effects"
    ),
    regexp = "unbounded"
  )
  # (1 | year) on a target that varies by age would share 1 random effect
  # across ages, so each would be scored once per age.
  with_log_m <- small_parameters |>
    dplyr::bind_rows(tibble::tibble(
      module_name = "Population",
      label = "log_M",
      age = 1:3,
      value = log(0.2),
      estimation_type = "constant"
    ))
  #' @description Test that `add_process()` errors for `(1 | year)` on a target that varies by age, and points to `(1 | age:year)`.
  expect_error(
    object = add_process(
      with_log_m,
      log_M ~ 1 + (1 | year),
      module_name = "Population"
    ),
    regexp = "age:year"
  )
  # Some years are fixed (no catch) and some are estimated.
  mixed <- small_parameters |>
    dplyr::mutate(estimation_type = dplyr::if_else(
      label == "log_Fmort" & timing == 1, "constant", estimation_type
    ))
  #' @description Test that `add_process()` errors for a target with some years fixed and some estimated.
  expect_error(
    object = add_process(
      mixed,
      log_Fmort ~ 1 + (1 | year),
      module_name = "Fleet",
      fleet = "fleet1"
    ),
    regexp = "some fixed"
  )
  with_prior <- small_parameters |>
    add_priors(
      log_q ~ normal(mean = log(0.5), sd = 0.2),
      module_name = "Fleet",
      fleet = "survey1"
    )
  #' @description Test that `add_process()` errors for a target that already has a prior and points to priors on the process's parameters.
  expect_error(
    object = add_process(
      with_prior,
      log_q ~ 1 + (1 | year),
      module_name = "Fleet",
      fleet = "survey1"
    ),
    regexp = "has a prior"
  )
})

test_that("`add_process()` returns correct error messages when finding the target", {
  # 2 fleets with a slope. Without `fleet`, the call would replace both
  # fleets' rows with 1 fleet's.
  two_fleets <- tibble::tibble(
    module_name = "Selectivity",
    fleet = c("fleet1", "survey1"),
    module_type = "Logistic",
    label = "slope",
    age = NA_real_,
    length = NA_real_,
    timing = NA_real_,
    value = 1,
    estimation_type = "fixed_effects",
    distribution_type = NA_character_,
    distribution = NA_character_
  ) |>
    dplyr::bind_rows(small_parameters)
  #' @description Test that `add_process()` errors when the target is in more than 1 fleet and no `fleet` is given.
  expect_error(
    object = add_process(
      two_fleets,
      slope ~ cut(year, c(-Inf, 3, Inf)),
      module_name = "Selectivity"
    ),
    regexp = "more than 1 fleet"
  )
  # Breaks outside the years give 1 group, such as breaks 10 and 20 with
  # calendar years.
  calendar_years <- small_parameters |>
    dplyr::mutate(timing = timing + 1989)
  #' @description Test that `add_process()` errors when the breaks put every year in the same time block.
  expect_error(
    object = add_process(
      calendar_years,
      log_q ~ cut(year, c(-Inf, 10, 20, Inf)),
      module_name = "Fleet",
      fleet = "survey1"
    ),
    regexp = "same group"
  )
  #' @description Test that `add_process()` errors for a formula in year on a target that is not indexed by year.
  expect_error(
    object = add_process(
      parameters_with_init_naa,
      log_init_naa ~ 1 + (1 | year),
      module_name = "Population"
    ),
    regexp = "not indexed by year"
  )
})
